{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "MSSQL Security Alert Policy missing email notification recipients",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The security alert policy does not specify 'email_account_admins' or 'email_addresses', meaning no one will be notified when critical threats like SQL injection are detected, delaying incident response."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Critical Threat Detection Alerts Disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "HIGH",
      "explanation": "The configuration explicitly disables alerts for 'Sql_Injection' and 'Data_Exfiltration', which are among the most severe database threats. This renders the threat detection policy ineffective against common attacks."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = []\n  retention_days             = 20\n  email_account_admins       = true\n}",
  "fix_summary": "Removed 'Sql_Injection' and 'Data_Exfiltration' from disabled_alerts to ensure all critical threats are monitored. Added 'email_account_admins = true' to ensure administrators receive immediate notifications for detected threats, addressing the lack of alert recipients."
}
